input.command:
cd /tmp/rt; cat > /tmp/t.bats <<'EOF'
@test x { run /tmp/rt/tools/check-round-independence.sh /tmp/rt/tests/fixtures/rounds/independent.md; echo "st=$status out=$output" >&3; }
EOF
bats /tmp/t.bats

cd ~/rt; yq --version; cat > .claude/scripts/compat-lib.sh <<'EOF'
sha256_portable(){ if [[ $# -gt 0 ]]; then sha256sum "$@"; else sha256sum | cut -d' ' -f1; fi; }
_date_to_epoch(){ date -u -d "$1" +%s; }
EOF
git init -q . 2>/dev/null; timeout 600 bats tests/unit/dec-write-lib.bats 2>&1 | tail -40

cd ~/rt; printf '## 10. Open Questions\n\n| Question | Owner | Due Date | Status | DEC |\n|---|---|---|---|---|\n| q | me | d | Unresolved | |\n| q2 | me | d | Open/Resolved | {DEC-NNNN once Resolved} |\n' > /tmp/s.md; awk '
        function trim(s) { gsub(/^[[:space:]]+|[[:space:]]+$/, "", s); return s }
        /^## 10\. Open Questions/ { sec = 1; next }
        sec && /^## / { sec = 0 }
        !sec { next }
        /^\|/ {
            n = split($0, c, "|")
            if (!hdr) { hdr = 1; for (i = 2; i < n; i++) { h = tolower(trim(c[i])); if (h == "status") st = i; if (h == "dec") dc = i }; next }
            if ($0 ~ /^\|[-|: ]+\|?[[:space:]]*$/) next
            if (st && tolower(c[st]) ~ /resolved/) { cell = dc ? c[dc] : $0; if (cell !~ /DEC-[0-9][0-9][0-9][0-9]/) printf "%d\n", NR }
        }' /tmp/s.md
